const {debugLog} = AiUtils.Debug;

const UNCHANGED_CONTEXT_PROMPT_NOTICE =
    'The selected context is unchanged since it was last provided earlier in this conversation.';

const SKILL_DISPLAY_NAMES: Record<SkillName, string> = {
  styling: 'CSS and styling',
  network: 'Network requests',
  performance: 'Performance',
  storage: 'Storage',
  sources: 'Sources',
  lighthouse: 'Lighthouse',
};

const MULTIMODAL_INPUT_PROMPTS: Record<MultimodalInputType, string> = {
  [MultimodalInputType.SCREENSHOT]:
      'The user attached a screenshot of the inspected page viewport. Use it alongside DevTools data when answering.',
  [MultimodalInputType.UPLOADED_IMAGE]: 'The user uploaded an image. Use it alongside DevTools data when answering.',
};

const MULTIMODAL_EVALUATION_GUIDELINES = `# Image Evaluation Guidelines
* Inspect the attached image first for details relevant to the user's request (such as visual layout, spacing, typography, colors, cropped or overlapping content, console or error messages, UI state, or reference designs).
* When inspecting a page screenshot or a selected context is provided, correlate what is visible in the image with live DevTools data (DOM, styles, network, sources, or performance) before drawing conclusions.
* **CRITICAL**: Interpret and use content and information from the image STRICTLY for web development and website debugging purposes.`;

const preamble = `You are the most advanced unified AI assistant integrated into Chrome DevTools.
Your role is to help web developers debug, analyze, and optimize web applications by learning specialized skills and utilizing tools.

# Style Guidelines
* **Precision and Brevity**: Use the precision of Strunk & White, the brevity of Hemingway, and the simple clarity of Vonnegut. Keep answers short, direct, and avoid repeated information or filler.
* **Tone**: Technical, precise, educational, and supportive.
* **No Self-Reference**: Do not mention that you are an AI, or refer to yourself in the third person. Simulate a senior web development expert.
* **No Internal Details**: Do not mention internal implementation details like the names of functions or tools you called (e.g., do not say "I called getStyles").

# Workflow
1. **Analyze**: Understand the user's intent, the context provided, and what they are trying to achieve.
2. **Investigate**: Proactively use your learned skills and tools to gather live data. Do not make assumptions or guess without sufficient evidence.
3. **Evaluate**: Synthesize the live data. If the user is debugging an issue, explore multiple potential explanations and distinguish between the primary root cause and contributing factors.
4. **Respond**: Match your response format and depth to the user's question.

# Response Structure
* **Informational or exploratory questions** (e.g., asking what a network request, script, element, or storage entry is or does):
  - Answer directly and concisely in 1–2 short paragraphs or a compact list of key facts.
  - Do NOT include "**Root Cause**" or "**Suggestions**" sections, and do not add unrequested optimization advice when nothing is broken.
* **Debugging, optimization, or unapplied edit requests (when no live page modification succeeded in this turn)** (including when no write tool ran, only read-only checks ran, or a modification attempt failed or was denied):
  - **Root Cause(s)** (include when diagnosing an issue): Point out the root cause(s) of the problem.
    - Example: "**Root Cause**: [reason]" or "**Root Causes**:" followed by a bulleted list.
  - **Suggestion(s)**: List actionable solution suggestion(s) in order of impact (if a live modification was denied or failed, first state briefly that the live change was not applied without naming internal tools).
    - Example: "**Suggestion**: [Suggestion]" or "**Suggestions**:" followed by a bulleted list.
  - Do NOT include an "**Applied Live Changes**" section when no live page modification succeeded in this turn.
* **Turns where a live page modification succeeded in this turn** (ONLY when a live style or page-modifying script call ran in the current turn and returned a non-error result):
  - **Root Cause(s)** (include when diagnosing a bug): Point out the root cause(s) of the problem.
  - **Applied Live Changes**: Detail the changes you applied to the live page (including the modified CSS properties or HTML attributes), note that these live changes are temporary and will reset on page reload, and ask the user to verify the result before updating their source code. Do NOT use "**Suggestion(s)**" or "**Suggested fix**" headings when you have already modified the live page.

# Follow-up Suggestions
* In the same message as your final Markdown answer, call the \`suggestFollowUps\` function to provide 1 to 3 relevant, concise follow-up queries or actions for the user.
* \`suggestFollowUps\` ends your turn immediately without another step. Never call \`suggestFollowUps\` with an empty text response or alongside other tool calls.
* Do not write follow-up suggestions as text in your response.

# Constraints
* **CRITICAL**: You are a web development assistant. NEVER provide answers to questions of unrelated topics (such as legal advice, financial advice, personal opinions, medical advice, religion, race, politics, sexuality, gender, or any other non-web-development topics). If asked about these, respond with: "Sorry, I can't answer that. I'm best at questions about web development and debugging."
* **CRITICAL**: Do not write standalone scripts (such as Python or bash) or arbitrary code to interact with the environment. The only way to execute code in the inspected page is via the 'executeJavaScript' tool.
* **CRITICAL**: Do not expose raw, internal system identifiers (such as database IDs, internal node paths, or event keys) directly to the user. Use descriptive names instead.
* **CRITICAL**: Stay read-only on informational (e.g., "what...", "where..."), diagnostic (e.g., "why..."), and how-to (e.g., "how do I...", "how can I...") queries. Do NOT modify live page state—even temporarily to test a hypothesis—(CSS styles, DOM nodes, text, attributes, scroll position, or simulated clicks/events) unless the user asks you to make a change, apply a fix, or run a live test (e.g., "make...", "change...", "fix...", "apply...", "try...", "click..."). When a live fix is possible on a read-only query, explain the solution first and offer to apply it on the live page (and include it as a follow-up suggestion).
* **CRITICAL**: Never claim to have made live page changes in this turn or include an "**Applied Live Changes**" section unless a live style or page-modifying script call ran in this turn and succeeded without an error or "Error:" output. Read-only queries, failed calls, and user-denied calls do not modify the live page. If asked about earlier turns, you may refer to edits that actually succeeded in those turns without claiming new changes in this turn.`;

/**
 * Snapshot of loaded skills, sent prompt facts, and context tracking for either
 * `#committedState` or an in-flight `#runDraft`.
 */
interface RunState {
  skills: Set<SkillName>;
  sentFacts: Set<PromptFact>;
  lastSentPromptDetails: string|null;
}

export interface AiAgent2Options extends ExecuteJsAgentOptions {
  /**
   * Supplies the origin lock state for the conversation.
   */
  originLock: () => OriginLockState;
  lighthouseRecording?: (overrides?: LHModel.RunTypes.RunOverrides) => Promise<LHModel.RunTypes.RunResult>;
  performanceRecordAndReload?: () => Promise<Trace.TraceModel.ParsedTrace>;
}

export class AiAgent2 extends AiAgent<unknown> {
  /**
   * Tracks skills, `PromptFact` instances, and context details committed to `AiAgent.#history`.
   * Facts are injected into append-only history rather than AIDA's wire `request.facts`
   * field (which `FactsToText` prepends to `current_message` on every step, repeating
   * tokens and invalidating prefix caching) or `getPromptDetails()` (which must stay
   * deterministic across turns for `lastSentPromptDetails` deduplication).
   */
  #committedState: RunState = {
    skills: new Set(),
    sentFacts: new Set(),
    lastSentPromptDetails: null,
  };
  /**
   * In-flight mutations during `run()` target this draft and promote to `#committedState` in `onRunCommitted()`.
   */
  #runDraft: RunState|null = null;

  /**
   * Routes reads and mutations to `#runDraft` during `run()`, or directly to
   * `#committedState` when idle or when `enhanceQuery()` or `learnSkill()` is called standalone outside `run()`.
   */
  get #state(): RunState {
    return this.#runDraft ?? this.#committedState;
  }

  /**
   * `#commitRun()` and `#createErrorResponse()` clear `#runDraft` on committed
   * and error paths, while `finally` rolls back uncommitted drafts on early
   * consumer `break` or empty-query returns.
   */
  override async *
      run(
          initialQuery: string,
          options: {
            selected: ConversationContext<unknown>|null,
            signal?: AbortSignal,
          },
          multimodalInput?: MultimodalInput,
          ): AsyncGenerator<ResponseData, void, void> {
    try {
      yield* super.run(initialQuery, options, multimodalInput);
    } finally {
      if (this.#runDraft) {
        this.clearCache();
      }
    }
  }

  /**
   * Discards the active `#runDraft` so uncommitted `skills`, `sentFacts`, and
   * `lastSentPromptDetails` from a failed run roll back while committed state
   * from earlier turns remains intact.
   */
  override clearCache(): void {
    super.clearCache();
    this.#runDraft = null;
    this.#pendingAutoLearnedSkills = [];
    this.#syncDeclaredFunctions();
  }

  /**
   * Appends any `facts` not yet recorded in `this.#state.sentFacts` to `content` under
   * `# References` with `## ${fact.title}` subheadings.
   */
  #appendUnsentFacts(content: string, facts: readonly PromptFact[] = []): string {
    const {sentFacts} = this.#state;
    const factSections: string[] = [];
    for (const fact of facts) {
      if (!sentFacts.has(fact)) {
        sentFacts.add(fact);
        factSections.push(`## ${fact.title}\n\n${fact.description.trim()}`);
      }
    }
    if (factSections.length === 0) {
      return content;
    }
    const references = `# References\n\n${factSections.join('\n\n')}`;
    return content ? `${content}\n\n${references}` : references;
  }

  // TODO: The static preamble is a placeholder and will eventually live server-side.
  readonly preamble: string = preamble;
  readonly clientFeature: Host.AidaClient.ClientFeature = Host.AidaClient.ClientFeature.CHROME_DEVTOOLS_V2_AGENT;
  get userTier(): string|undefined {
    return Root.Runtime.hostConfig.devToolsAiV2Architecture?.userTier;
  }

  #changes: ChangeManager;
  #execJs: typeof executeJsCode;
  readonly #originLock: () => OriginLockState;
  readonly #lighthouseRecording?: (overrides?: LHModel.RunTypes.RunOverrides) => Promise<LHModel.RunTypes.RunResult>;
  readonly #performanceRecordAndReload?: () => Promise<Trace.TraceModel.ParsedTrace>;

  get options(): RequestOptions {
    return {};
  }

  protected override async preRun(): Promise<void> {
    // Initialize a fresh draft from committed state to isolate mutations during this run.
    this.#runDraft = {
      skills: new Set(this.#committedState.skills),
      sentFacts: new Set(this.#committedState.sentFacts),
      lastSentPromptDetails: this.#committedState.lastSentPromptDetails,
    };
    this.#syncDeclaredFunctions();
    await super.preRun();
    // One-way latch: once sensitive data enters the conversation history,
    // logging must remain disabled for the lifetime of this agent instance.
    if (this.context && !this.context.isLoggingEnabled()) {
      this.disableServerSideLogging();
    }

    const target = this.targetManager.primaryPageTarget();
    const originLock = this.#originLock();
    // Avoid fetching or caching top-level documents across origins or when
    // the origin lock is blocked/uninitialized.
    const isTargetAllowed = target && isOriginAllowedByLock(originLock, target.inspectedSecurityOrigin());
    const domModel = isTargetAllowed ? target.model(SDK.DOMModel.DOMModel) : null;
    // Ensure the DOM document is requested and cached in DOMModel so that
    // subsequent synchronous lookups via domModel.existingDocument() (e.g.,
    // in #getDefaultExecutionContextNode()) resolve the document and body immediately.
    if (domModel) {
      if (!domModel.existingDocument()) {
        try {
          await domModel.requestDocument();
        } catch (e) {
          debugLog('AiAgent2: Failed to request document', e);
        }
      }
      const document = domModel.existingDocument();
      // Fetching documentElement's children populates document.body in DOMModel as a side effect.
      if (document && !document.body && document.documentElement) {
        try {
          await document.documentElement.getChildNodesPromise();
        } catch (e) {
          debugLog('AiAgent2: Failed to request documentElement child nodes', e);
        }
      }
    }
  }

  /**
   * Tracks skills auto-loaded during enhanceQuery() so handleContextDetails() can attach them to ContextResponse for telemetry without rendering a walkthrough step.
   */
  #pendingAutoLearnedSkills: SkillName[] = [];

  constructor(opts: AiAgent2Options) {
    super({
      ...opts,
      allowedOrigin: opts.allowedOrigin ?? (() => {
                       const lock = opts.originLock();
                       if (lock.status === 'BLOCKED_BY_NAVIGATION') {
                         return {blocked: true};
                       }
                       if (lock.status === 'ESTABLISHED_ORIGIN') {
                         return {origin: lock.origin};
                       }
                       return {origin: undefined};
                     }),
    });
    this.#changes = opts.changeManager ?? new ChangeManager(opts.targetManager);
    this.#lighthouseRecording = opts.lighthouseRecording;
    this.#performanceRecordAndReload = opts.performanceRecordAndReload;
    this.#execJs = opts.execJs ?? executeJsCode;
    this.#originLock = opts.originLock;

    this.#syncDeclaredFunctions();
  }

  /**
   * Registers baseline functions (`learnSkills` and `suggestFollowUps`) that are
   * always available regardless of which domain skills are loaded.
   */
  #declareCoreFunctions(): void {
    const skillsManifest = Object.entries(SKILLS).map(([name, skill]) => `- ${name}: ${skill.description}`).join('\n');
    this.declareFunction<{skills: SkillName[]}>('learnSkills', {
      description: `Loads the specified skills to gain access to their specialized tools and instructions.
If the user's request requires a skill that has not been loaded yet in this conversation, you MUST call \`learnSkills\` to load that skill first before using its tools, instead of attempting to solve the query using tools from other skills.
Do NOT call \`learnSkills\` for skills that were already loaded earlier in this conversation.

Available skills:
${skillsManifest}`,
      parameters: {
        type: Host.AidaClient.ParametersTypes.OBJECT,
        description: 'Parameters for learning skills',
        properties: {
          skills: {
            type: Host.AidaClient.ParametersTypes.ARRAY,
            items: {
              type: Host.AidaClient.ParametersTypes.STRING,
              description: 'Skill name',
            },
            description: 'List of skill names to load (only include skills not yet loaded in this conversation)',
          },
        },
        required: ['skills'],
      },
      displayInfoFromArgs: args => {
        const isSingular = args.skills.length === 1;
        const prefix = isSingular ? 'Learning skill' : 'Learning skills';
        const names = args.skills.map(name => SKILL_DISPLAY_NAMES[name] ?? name).join(', ');
        return {
          title: `${prefix}: ${names}`,
          action: `learnSkills(${args.skills.map(name => `'${name}'`).join(', ')})`,
        };
      },
      handler: async args => {
        const previouslyLoaded = new Set(this.activeSkills);
        const result = await this.learnSkill(args.skills);
        // The LLM may hallucinate skill names. Filter out any skills that were not newly activated.
        const loadedSkills =
            [...new Set(args.skills)].filter(skill => !previouslyLoaded.has(skill) && this.activeSkills.has(skill));
        return {
          result,
          loadedSkills: loadedSkills.length > 0 ? loadedSkills : undefined,
        };
      },
    });
    this.declareFunction<{suggestions: string[]}>(SUGGEST_FOLLOW_UPS_FUNCTION_NAME, {
      description:
          'Provides suggested follow-up queries or actions for the user. Ends the turn immediately: call this only in the same message as your final non-empty Markdown response, never alone with empty text or alongside other tool calls.',
      parameters: {
        type: Host.AidaClient.ParametersTypes.OBJECT,
        description: 'Parameters for follow-up suggestions',
        properties: {
          suggestions: {
            type: Host.AidaClient.ParametersTypes.ARRAY,
            items: {
              type: Host.AidaClient.ParametersTypes.STRING,
              description: 'A concise follow-up query or action (under 60 characters).',
            },
            description: '1 to 3 concise follow-up queries or actions relevant to the response.',
          },
        },
        required: ['suggestions'],
      },
      // Never called: AiAgent#run() and AiAgent#runFunctionCalls() intercept suggestFollowUps directly.
      handler: async () => ({result: 'Suggestions recorded.'}),
    });
  }

  /**
   * Rebuilds `AiAgent.#functionDeclarations` from `this.activeSkills` so declared
   * tools match the active draft or committed skills, preserving tools shared
   * between committed and rolled-back skills.
   */
  #syncDeclaredFunctions(): void {
    this.clearDeclaredFunctions();
    this.#declareCoreFunctions();
    const toolNames = new Set([...this.activeSkills].flatMap(name => SKILLS[name]?.allowedTools ?? []));
    for (const toolName of toolNames) {
      const tool = ToolRegistry.get(toolName);
      if (tool) {
        this.#declareTool(tool);
      }
    }
  }

  /**
   * Promotes the completed `#runDraft` into `#committedState`.
   */
  protected override onRunCommitted(): void {
    if (this.#runDraft) {
      this.#committedState = this.#runDraft;
      this.#runDraft = null;
    }
  }

  /**
   * Maps selected contexts (DOMNodeContext, RequestContext, FileContext) to their domain skill to skip a redundant step-1 learnSkills round trip.
   */
  #skillForContext(selected: ConversationContext<unknown>|null): SkillName|null {
    if (selected instanceof DOMNodeContext) {
      return 'styling';
    }
    if (selected instanceof RequestContext) {
      return 'network';
    }
    if (selected instanceof FileContext) {
      return 'sources';
    }
    return null;
  }

  /**
   * Builds the user-turn prompt prefix in order: auto-loaded skill instructions,
   * deduplicated selected context with unsent facts, and turn-scoped multimodal
   * guidance directly before `# User request`.
   *
   * Multimodal guidance stays outside `lastSentPromptDetails` deduplication so it
   * applies only to turns with an attached image, and runs unconditionally when
   * `multimodalInputType` is passed because feature-flag gating lives in
   * `AiAssistancePanel` rather than inside `AiAgent2`.
   */
  override async enhanceQuery(
      query: string,
      selected: ConversationContext<unknown>|null = null,
      multimodalInputType?: MultimodalInputType,
      ): Promise<string> {
    this.#pendingAutoLearnedSkills = [];
    const promptDetails = selected ? await selected.getPromptDetails() : null;
    let contextDetails = '';
    if (!promptDetails) {
      // Clear the tracker when there is no context (or an unsupported context type)
      // so that if the user later switches back to a previously sent context, it is
      // sent in full again rather than deduplicated.
      this.#state.lastSentPromptDetails = null;
    } else {
      contextDetails =
          promptDetails === this.#state.lastSentPromptDetails ? UNCHANGED_CONTEXT_PROMPT_NOTICE : promptDetails;
      this.#state.lastSentPromptDetails = promptDetails;
    }

    // `autoLoadedBlock` precedes the context section in the final prompt. Run `learnSkill` before
    // appending context facts so shared facts render at the top with the skill instructions.
    let autoLoadedBlock = '';
    const mappedSkill = this.#skillForContext(selected);
    if (mappedSkill && SKILLS[mappedSkill] && !this.activeSkills.has(mappedSkill)) {
      autoLoadedBlock = await this.learnSkill([mappedSkill]);
      this.#pendingAutoLearnedSkills.push(mappedSkill);
    }

    const contextBlock = this.#appendUnsentFacts(contextDetails, selected?.getPromptFacts());
    const multimodalBlocks =
        multimodalInputType ? [MULTIMODAL_INPUT_PROMPTS[multimodalInputType], MULTIMODAL_EVALUATION_GUIDELINES] : [];
    const prefix = [autoLoadedBlock, contextBlock, ...multimodalBlocks].filter(Boolean).join('\n\n');
    return prefix ? `${prefix}\n\n# User request\n\nQUERY: ${query}` : query;
  }

  /**
   * `AiAgent2` receives follow-up suggestions from `suggestFollowUps` tool
   * calls rather than text parsing. Overrides `AiAgent#parseTextResponse()` so
   * V2 responses do not inherit V1 `parseTextResponseForSuggestions()`.
   */
  override parseTextResponse(response: string): ParsedResponse {
    return {answer: response.trim()};
  }

  override async *
      handleContextDetails(selected: ConversationContext<unknown>|null): AsyncGenerator<ContextResponse, void, void> {
    const autoLearned = this.#pendingAutoLearnedSkills;
    this.#pendingAutoLearnedSkills = [];
    if (!selected) {
      return;
    }

    const [details, widgets] = await Promise.all([
      selected.getUserFacingDetails(),
      selected.getWidgets(),
    ]);
    if (details) {
      // Do not yield a separate TITLE/ACTION walkthrough step for autoLearned skills:
      // DevTools attaches the active panel's selected item before the model evaluates
      // whether the user's question needs that skill, so showing "Loaded skill: ..."
      // in the walkthrough misleads the user when their question is about another domain.
      yield {
        type: ResponseType.CONTEXT,
        details,
        ...(widgets.length > 0 ? {widgets} : {}),
        ...(autoLearned.length > 0 ? {autoLearnedSkills: autoLearned} : {}),
      };
    }
  }

  async learnSkill(names: SkillName[]): Promise<string> {
    const sections: string[] = [];
    let skillsAdded = false;
    for (const name of names) {
      if (this.activeSkills.has(name)) {
        debugLog(`[AiAgent2] Skill '${name}' is already loaded`);
        sections.push(`Error: Skill '${
            name}' is already loaded. Call its tools directly instead of invoking learnSkills for '${name}' again.`);
        continue;
      }

      const skillObj = SKILLS[name];
      if (skillObj) {
        this.activeSkills.add(name);
        skillsAdded = true;
        debugLog(`[AiAgent2] Loaded skill '${name}' with tools: [${skillObj.allowedTools.join(', ')}]`);
        const instructions = this.#appendUnsentFacts(skillObj.instructions.trim(), skillObj.facts);
        sections.push(`Skill ${name} loaded. Instructions:\n${instructions}`);
      } else {
        debugLog(`[AiAgent2] Failed to load skill '${name}'`);
        sections.push(`Failed to load skill ${name}. Valid skills are: ${Object.keys(SKILLS).join(', ')}.`);
      }
    }
    if (skillsAdded) {
      this.#syncDeclaredFunctions();
    }
    return sections.join('\n\n');
  }

  #getExecutionContextNode(): SDK.DOMModel.DOMNode|null {
    if (this.context instanceof DOMNodeContext) {
      return this.context.getItem();
    }
    return this.#getDefaultExecutionContextNode();
  }

  #createExtensionScope(changes: ChangeManager): {install(): Promise<void>, uninstall(): Promise<void>} {
    return new ExtensionScope(changes, this.sessionId, this.#getExecutionContextNode());
  }

  /**
   * Registers a tool declaration on AiAgent with the capability context.
   * Deduplication across skills is handled by #syncDeclaredFunctions().
   */
  #declareTool(tool: Tool<ToolArgs, unknown, AllToolsCapabilities>): void {
    this.declareFunction(tool.name, {
      description: tool.description,
      parameters: tool.parameters,
      displayInfoFromArgs: tool.displayInfoFromArgs,
      permissionPrompt: tool.permissionPrompt,
      permissionTitle: tool.permissionTitle,
      handler: (args, options) => {
        const context: AllToolsCapabilities = {
          changeManager: this.#changes,
          createExtensionScope: this.#createExtensionScope.bind(this),
          execJs: this.#execJs,
          getExecutionContextNode: () => this.#getExecutionContextNode(),
          getTarget: () => this.#getTarget(),
          getOriginLock: () => this.#originLock(),
          getLighthouseReport: () => (this.context instanceof LighthouseContext ? this.context.getItem() : null),
          runLighthouse: async overrides => await (this.#lighthouseRecording?.(overrides) ?? {status: 'failed'}),
          getPerformanceTraceContext: () => (this.context instanceof PerformanceTraceContext ? this.context : null),
          performanceRecordAndReload: this.#performanceRecordAndReload,
          disableLogging: () => {
            this.disableServerSideLogging();
          },
        };
        return tool.handler(args, context, options);
      },
    });
  }

  /**
   * Returns the primary page target unless origin access is explicitly blocked
   * (e.g. following cross-origin navigation).
   * Tools use this target to resolve node IDs and fetch frame resources, and
   * perform their own origin checks on the resolved entities.
   */
  #getTarget(): SDK.Target.Target|null {
    if (this.#originLock().status === 'BLOCKED_BY_NAVIGATION') {
      return null;
    }
    return this.targetManager.primaryPageTarget();
  }

  /**
   * For non-DOM contexts (e.g., Lighthouse accessibility reports or storage items),
   * there is no user-selected DOM node. Falls back to `document.body` and then
   * `document.documentElement` so scripts have a valid Element `$0` target even
   * on HTML documents without a `<body>` (such as framesets).
   * Returns null if no document, body, or documentElement exists, or if the
   * conversation origin is not established or does not match the primary page
   * document's security origin.
   */
  #getDefaultExecutionContextNode(): SDK.DOMModel.DOMNode|null {
    const target = this.#getTarget();
    const document = target?.model(SDK.DOMModel.DOMModel)?.existingDocument();
    if (!document) {
      return null;
    }
    const originLock = this.#originLock();
    if (!isOriginAllowedByLock(originLock, document.securityOrigin())) {
      return null;
    }
    return document.body ?? document.documentElement ?? null;
  }

  /**
   * Returns the active draft's skills during `run()`, or `#committedState.skills` when idle.
   */
  get activeSkills(): Set<SkillName> {
    return this.#state.skills;
  }
}
